        "921": { n: "Nega betona (temperaturno-vlažnosni režim)", t: "Košuljice i monolitne prevlake na cementnom vezivu treba čuvati u vlažnim uslovima ne manje od 7 dana nakon polaganja, pod slojem materijala koji čuva vlagu, ako drugačije nije predviđeno od strane proizvođača materijala. SP 71.13330.2017 8.1.12" },
        "922": { n: "Pad", t: "Nekorišćen i inverzni krov: ne manje od 1,5% (SP 17.13330.2017, tač. 5.1.4).\nKorišćeni krov: 1,5-3,0% (SP 17.13330.2017, tabela 4.1)." },
        "923": { n: "Sečenje na trake/table", t: "PIR. SP 71.13330.2017 t.5.1.9: temperaturno-skupljajući spojevi širine do 10 mm dele cementno-peščani sloj na table najviše 6×6 m, a peščani asfaltbeton na table najviše 4×4 m" },
        "924": { n: "Celovitost", t: "Interni standard kompanije (tehničko uputstvo TehnoNIKOL za izvođenje krovova (priprema podloge)). Bez rupica, bez prslina" },
        "925": { n: "Tip pokrivača odgovara projektu", t: "Projekat" },
        "926": { n: "Završni pokrivač", t: "PIR. Bez oštećenja, ne dozvoljavaju se udubljenja, ogrebotine do metala (za metalne krovove), pocepotine (za rolne materijale), odlomljeni delovi." },
