        "1207": { n: "Marka čelika zavrtnjeva, navrtki, podložnih pločica.", t: "GOST 32484.3-2013, GOST 1759.4-87\nUsaglašenost s projektom (obično klasa čvrstoće 5.8, 8.8, 10.9)" },
