        "2506": { n: "Obeležavanje osa polja šipova, kota repera", t: "SP 126.13330.2017 tač. 7.3, tabela 7.1: granična greška međusobnog položaja susednih osa — 5 mm u osnovi, 10 mm po visini" },
        "2507": { n: "Priprema podloge za postavljanje (nasip)", t: "SP 45.13330.2017 (tačka 4.3, 4.7, 4.12); Usaglašenost sa PIR, obezbeđivanje stabilnosti" },
        "2508": { n: "Spoljašnji izgled šipova (odsustvo prslina, odloma, izliva)", t: "Odsustvo prslina, ogoljene armature, izliva betona. (GOST 13015-2012 tač. 5.5)" },
        "2509": { n: "Geometrijske dimenzije (dužina, presek)", t: "±10 mm po dužini; ±5 mm po preseku (GOST 19804-2021 tač. 6.13)" },
        "2510": { n: "Obeležavanje šipova", t: "Interni standard kompanije (GOST 23009-2016 reguliše format oznake, a ne njeno mesto): na rastojanju 500 mm od kraja ili na kraju šipa" },
        "2511": { n: "Sertifikati i deklaracije za šipove", t: "(GOST 13015 tač. 5.6.10) (sa obaveznim naznakom mrazootpornosti i vodonepropusnosti betona)" },
        "2512": { n: "Položaj šipa u osnovi pre utiskivanja", t: "Vidi tabelu 12.1 SP 45.13330.2017 (za šipove do 0,5 m: ±10 mm bez vodilice)" },
        "2513": { n: "Vertikalnost postavljanja šipa", t: "Interni standard kompanije (tabela 12.1 SP 45.13330.2017 navodi 2% za nabijene šipove; norma za utisnute šipove nije pronađena). Odstupanje od vertikale ne veće od 1,5% (ili prema deklaraciji opreme)" },
        "2514": { n: "Dubina utiskivanja / projektni otkaz", t: "Usaglašenost s projektom (projektna kota ili vrednost otkaza)" },
        "2515": { n: "Kontrola procesa utiskivanja", t: "SP 45.13330.2017 tač. 12.1.9, Prilog E.3 (kontrola po dubini utiskivanja i sili utiskivanja; registracija sile na svakih 10 cm poslednjih 50 cm). Odsustvo naglih skokova sile i iskošenja, ravnomerno kretanje — interni standard kompanije" },
        "2516": { n: "Kota vrha šipa nakon utiskivanja", t: "±3 cm (za monolitnu roštilj-gredu) - tabela 12.1 SP 45.13330.2017" },
        "2517": { n: "Kvalitet zavarenog šva spoja segmenata", t: "GOST 5264-80, GOST 14771-76 (tipovi i konstruktivni elementi šavova); kontrola kvaliteta zavarenih spojeva — SP 70.13330.2012 odeljak 10" },
        "2518": { n: "Koaksijalnost segmenata", t: "Odsustvo preloma po osi, usaglašenost s radnom dokumentacijom (tač. 12.1.7 SP 45.13330.2017)" },
        "2519": { n: "Antikorozivna obrada zavarenog šva", t: "Usaglašenost s radnom dokumentacijom i PIR (tač. 9.3.11 SP 28.13330)" },
        "2520": { n: "Statička ispitivanja opterećenjem utiskivanja", t: "Program ispitivanja usaglašen sa Investitorom i Glavnim projektantom" },
        "2521": { n: "Broj ispitanih šipova", t: "Do 0,5–1% od partije (statička ispitivanja opterećenjem utiskivanja), ali ne manje od 2 kom. (tač. 7.3.1 SP 24.13330.2021)" },
        "2522": { n: "Zapisnici o skrivenim radovima (pregled pre utiskivanja, spajanje, antikorozivna zaštita)", t: "Naredba Ministarstva građevinarstva RF od 16.05.2023. br. 344/PR" },

        "2601": { n: "Potpisan zapisnik o preuzimanju fronta radova", t: "Interni standard kompanije (SP 71.13330.2017 ne reguliše primopredaju fronta radova; tematski — organizacija građenja, SP 48.13330)" },
        "2602": { n: "Materijali se koriste u skladu s projektom, TZ", t: "SP 48.13330.2019 Prilog B, B.1 (stavke 7, 8); Projekat. Deklaracije kvaliteta, sertifikati za korišćene materijale dostavljeni" },
        "2603": { n: "Usaglašen PIR", t: "SP 70.13330 tač.3.3" },
        "2604": { n: "Izvođački crteži izvedeni", t: "SP 70.13330 tač.3.5, 3.23" },
        "2605": { n: "Temperaturno-vlažnosni režim", t: "SP 70.13330.2012, tač. 5.4.1, 5.11.17, 5.12.3. Ne niže od +5°S. Promaja se ne dozvoljava. Kod izvođenja podova na neizolovanim tavanicama temperatura vazduha u prostoriji ispod mora biti ne niža od +5°S. Čuvati u vlažnim uslovima pod slojem folije ne manje od 7 dana." },
        "2606": { n: "Podloga", t: "SP 71.13330.2017, tač. 8.2.1. Ne dozvoljava se prisustvo otpada. Površina ploče maksimalno oslobođena prašine" },
        "2607": { n: "Postavljanje razdvojnog sloja (folija)", t: "Interni standard kompanije (tehnološke karte polusuve košuljice (folija, preklopi)). Prema projektu. Preklop 15–20 cm, debljina ≥200 µm" },
        "2608": { n: "Mesta prolaza instalacija zadelana betonom", t: "Interni standard kompanije (tipska tehnološka karta polusuve košuljice (zaptivanje otvora)). Pre početka radova na izradi košuljice neophodno je mesta prolaza instalacija zadelati betonom" },
        "2609": { n: "Montaža dilatacione (demperske) trake", t: "Interni standard kompanije (tehnološke karte košuljice i specifikacije proizvođača trake). Monolitne košuljice izolovane od zidova i pregrada trakama od hidroizolacionih materijala i dilatacionim trakama. Debljina ≥10 mm. Odsustvo prekida" },
        "2610": { n: "Vlažnost podloge", t: "SP 71.13330.2017, odeljak 8. Dozvoljena vlažnost monolitne podloge – 5%" },
        "2611": { n: "Projektna debljina termo- i zvučne izolacije", t: "Debljina, tip i marka termo- i zvučne izolacije — prema projektu / deklaraciji materijala" },
        "2612": { n: "Postavljanje ploča", t: "SP 71.13330.2017, tač. 8.5.1–8.5.2. Ploče se moraju postavljati na podlogu čvrsto jedna uz drugu i imati jednaku debljinu. Postavljanje ploča u razmaku. Prekidi u zvučnoizolacionom sloju se ne dozvoljavaju" },
        "2613": { n: "Debljina košuljice", t: "Interni standard kompanije (tehnološke karte polusuve košuljice (debljina 40-50 mm)). Prema projektu. ≥30 mm (stambeni prostori), ≥50 mm (opterećenja). Odstupanje ≤2 mm/2 m" },
        "2614": { n: "Upotreba dodataka protiv smrzavanja pri mešanju", t: "SP 70.13330.2012 (prag za upotrebu dodataka protiv smrzavanja / zimsko betoniranje). Pri temperaturi ispod +5°S" },
        "2615": { n: "Priprema rastvora", t: "Prema projektu, zahtev na pritisak. Upotreba fibera." },
        "2616": { n: "Primena dodatnog armiranja na mestima prolaza cevovoda", t: "Prema projektu" },
        "2617": { n: "Odstupanje od horizontale i lokalne neravnine", t: "PIR. Pad do 0,2% ali ne više od 50 mm na prostoriju (SP 71.13330.2017, tabela 8.5). Kod hidroizolacije – 5 mm. Košuljice pod laminat, parket, linoleum – 2 mm. Pod ostale tipove – 4 mm." },
        "2618": { n: "Izrada temperaturno-skupljajućih spojeva", t: "Projekat, PIR, SP 29.13330.2011, tač. 8.14. Korak ≤6 m. Na granicama različitih prostorija." },
        "2619": { n: "Kvalitet zaglađivanja površine", t: "SP 71.13330.2017, tabela 8.2. Bez vidljivih defekata, neravnina površine, kvalitetno zaglađena" },
        "2620": { n: "Čvrstoća na pritisak gotove košuljice nakon 28 dana", t: "Tehnička karta ≥20 MPa (SP 29.13330.2011, tač. 8.5 — košuljica preko elastičnog termo- i zvučnoizolacionog sloja, klasa betona ne niža od B15)" },
        "2621": { n: "Poštovanje temperaturno-vlažnosnog režima u periodu sušenja", t: "SP 70.13330.2012, tač. 5.4.1, 5.11.17, 5.12.3. Ne dozvoljava se: promaja, vlažni uslovi ne manje od 7 dana nakon postavljanja (prekrivanje folijom), održavanje temperaturno-vlažnosnog režima ne nižeg od +5°S" },
        "2622": { n: "Odsustvo vidljivih defekata", t: "Interni standard kompanije (tipska tehnološka karta polusuve košuljice (prijem radova)). Ne dozvoljava se: prsline širine ≤0,5 mm, dužine ≤100 mm, uvijanje uglova." },
        "2623": { n: "Priprema podloge, impregnacija", t: "SP 71.13330.2017, tač. 8.6.3. Oslobađanje od prašine, nanošenje grunda pre hidroizolacije" },
        "2624": { n: "Rolni materijali (nalepni)", t: "SP 71.13330.2017, tač. 8.6.3. Preklop traka ne manji od 80 mm. Ne dozvoljavaju se preskoci, nekvalitetno lepljenje, oštećenja." },
        "2625": { n: "Polimerna mastika", t: "SP 71.13330.2017, tač. 8.6.4, 8.6.5. Preskoci se ne dozvoljavaju. Nanošenje ne manje od 2 sloja. Na mestima naslanjanja neprekidno na visinu ne manju od 200 mm od nivoa podnog pokrivača. Ojačanje uglova mrežicom." },
        "2626": { n: "Rastvori na bazi cementa", t: "SP 71.13330.2017, tač. 8.6.4, 8.6.5. Preskoci se ne dozvoljavaju. Nanošenje ne manje od 2 sloja. Na visinu ne manju od 200 mm. Armirati metalnom mrežicom 10x10 do 20x20 mm." },

