        "2702": { n: "Materijali se koriste u skladu s projektom ili su usaglašeni", t: "SP 48.13330.2019 Prilog B, tač. B.1, stavka 7; Projekat" },
        "2703": { n: "Rezultati ispitivanja tiplova, ankera", t: "SP 48.13330.2019 Prilog B, B.1 (stavka 8)" },
