        "2705": { n: "Postojanje usaglašenog PIR", t: "SP 70.13330 tač.3.3" },
        "2706": { n: "Čišćenje podloge", t: "SP 293.1325800.2017 tač.8.1.5.2: sa podloge ukloniti odlepljujuće se deonice; defekte veće od 10 mm popuniti reparaturnim materijalima; očistiti od prašine i izloga" },
        "2707": { n: "Ravnost", t: "SP 70.13330 tač.5.18. Odstupanje podloge od ravni ne veće od 20 mm" },
        "2708": { n: "Impregnacija podloge ojačavajućim grundom", t: "PIR. Ravnomerno impregnisana površina primenom kolera" },
        "2709": { n: "Temperatura podloge, temperatura vode pri mešanju rastvora", t: "SP 293.1325800.2017 tač. 8.1.10: izvođenje radova pri temperaturi vazduha od +5°S do +30°S. Interni standard kompanije: temperatura podloge ne niža od +5°S, temperatura vode +15°S do +30°S (SP normira vodu za mešanje samo za snižene temperature — (25±2)°S, tač. 8.3.4)" },
        "2710": { n: "Kontrola nanošenja lepljivog sastava", t: "SP 293.1325800.2017, tač.8.2.3.2. Rastvor se nanosi na ploču trakom širine 5–8 cm i debljine 1–2 cm po celom obimu ploče sa odstupanjem od ivica 2–3 cm i dodatno 3–6 „kupa“ u srednjem delu. Odsustvo lepljivog sastava na krajevima ploča." },
        "2711": { n: "Preklop izolacije na okvir prozorskih i vratnih blokova", t: "SP 293.1325800.2017, tač.8.2.3.5. Ploče se postavljaju sa preklopom na okvir bloka ne manjim od 20 mm" },
        "2712": { n: "Izrada kosina (ugao)", t: "RBI standard, ne manje od 90° po celom obimu u odnosu na prozor ili vrata" },
        "2713": { n: "Celovitost izolacije, temperaturno-vlažnosni režim", t: "Interni standard kompanije (Ceresit (Henkel) uputstvo za montažu SFTK: zaštita MV od vlaženja). Ugrađena izolacija nije oštećena, kvašenje mineralne izolacije SE NE DOZVOLJAVA. Namočena mineralna izolacija mora biti DEMONTIRANA" },
        "2714": { n: "Odstupanje ravni ugrađene izolacije", t: "SP 293.1325800.2017 tabela 8.2: odstupanje ravni izolacije ±2 mm na 2 m (horizontalno i vertikalno). Stepenik između ploča ≤1,5 mm" },
        "2715": { n: "Zazori između ploča", t: "SP 293.1325800.2017, tač. 8.2.3.7. Dozvoljeni zazor ≤2 mm. Zazore veće od 2 mm popuniti materijalom." },
        "2716": { n: "Vezivanje vertikalnih spojeva izolacije", t: "SP 293.1325800.2017 tač.8.2.3.4. Vezivanje u svakom redu, na spoljašnjim i unutrašnjim uglovima zupčasto sprezanje ploča" },
        "2717": { n: "Izrada ugaonog izreza mineralne ploče oko otvora", t: "SP 293.1325800.2017, tač.8.2.3.5. Spojevi su na rastojanju ne manjem od 150 mm od ugla otvora" },
        "2718": { n: "Ankerovanje mineralne ploče", t: "Interni standard kompanije (SP 293.1325800.2017 tač.8.2.4.1 ne sadrži ove fiksne brojeve - broj/šemu ankera određuje projekat; minimum od 5 kom/m² je u tač.7.35.1, proračun po zonama je preko formule Priloga V). Unutrašnja zona: visina ≤40 m - 5 kom. na m²; visina > 40 m - 6 kom. na m². Rubna zona od 1,2 do 2 m: visina ≤16 m - 5 kom. na m²; visina > 16 ali ≤40 m - 8 kom. na m²; visina > 40 m - 10 kom. na m²." },
        "2719": { n: "Montaža tanjirastog tipla sa ankerom", t: "SP 293.1325800.2017 (sa Izmenom br.1/2), tabela 8.2 „Kontrolisani parametri pri izradi SFTK\": tanjirasti disk mora biti u ravni s površinom ploče ili uvučen ne više od 2 mm. Termoglava neoštećena." },
        "2720": { n: "Priprema lepljivog sastava", t: "Interni standard kompanije (Tehnički list Ceresit CT 190: čista posuda i doziranje vode). Mešanje se vrši u čistoj posudi. Odnos vode i lepljivog sastava se poštuje." },
        "2721": { n: "Montaža staklene mrežice", t: "Preklop mrežice ne manji od 100 mm (SP 293.1325800.2017, tač. 8.2.5.1/8.2.5.4). Mrežica se lepi utiskivanjem. Ojačanje uglova dijagonalnim elementima („kravatama“) ne manjim od 200×400 mm (SP 293.1325800.2017, tač. 7.22). Pre početka armiranja na prozorske okvire lepi se PRIMAJUĆI PROFIL od PVC profila sa lentom za otkidanje." },
        "2722": { n: "Kontrola debljine armiranog baznog sloja", t: "SP 293.1325800.2017 tač.8.2.5.4. Debljina baznog sloja 3-4 mm (ili nazubljenom gletericom sa zubom od 10 mm). Debljina dodatnog sloja 1-2 mm. Staklena mrežica mora da izviri najmanje 1 mm." },
        "2723": { n: "Odstupanje ravni malterskog sloja", t: "Interni standard kompanije (weber.therm SFTK uputstvo: neravnina do 3 mm na 2 m). Odstupanja ravni +/- 3 mm na 2 m" },
        "2724": { n: "Temperatura spoljašnjeg vazduha.", t: "+5°S - +30°S (SP 293.1325800.2017, tač. 8.1.10)" },
        "2725": { n: "Neravnomernost impregnacije", t: "Interni standard kompanije (SNiP 3.04.01-87 t.3.25: gruntiranje u neprekidnom ravnomernom sloju). Ne dozvoljava se" },
        "2726": { n: "Prisustvo pruga, mrlja, curenja, nabora", t: "Interni standard kompanije (SNiP 3.04.01-87 t.3.25: gruntiranje bez propusta i curenja). Ne dozvoljava se" },
        "2727": { n: "Temperatura spoljašnjeg vazduha", t: "+5°S - +30°S (SP 293.1325800.2017, tač. 8.1.10)" },
        "2728": { n: "Providnost prethodnih slojeva boje", t: "Interni standard kompanije (SNiP 3.04.01-87: providnost donjih slojeva boje nije dozvoljena). Ne dozvoljava se" },
        "2729": { n: "Neravnomernost linija farbanja na spojevima površina", t: "Interni standard kompanije (SNiP 3.04.01-87: zahtevi za linije bojenja na spojevima). Ne dozvoljava se" },
        "2730": { n: "Neusaglašenost boja fasade sa uzorcima kolera", t: "Interni standard kompanije (SNiP 3.04.01-87 t.1.2: obrada prema projektu i odobrenom etalonu). Ne dozvoljava se" },

        "9901": { n: "Usaglašenost s radnom dokumentacijom (RD) i TZ", t: "Materijali, vezivanja i geometrija potpuno su usaglašeni s RD." },
